 9	func (s *Server) GetUser(w http.ResponseWriter, r *http.Request) {
10		id := r.URL.Query().Get("id")
11		if id == "" {
12			http.Error(w, "missing id", http.StatusBadRequest)
13			return
14		}
15		v, ok := s.store.Get("user:" + id)
16		if !ok {
17			http.Error(w, "not found", http.StatusNotFound)
18			return
19		}
20		w.Write([]byte(v))
21	}
